const D = { scale: 1, energy: .6, density: .55, speed: 1, states: 14, hue: 0, x: .5, y: .5, style: 'pinwheel', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- grid dims (scale -> cell size; larger scale = chunkier cells / coarser grid) ----
const CW = Math.max(56, Math.min(176, Math.round(150 / Math.max(0.35, P.scale))));
const CH = Math.max(40, Math.min(176, Math.round(CW * height / Math.max(1, width))));
const N = Math.max(3, Math.min(24, P.states | 0));
const seedI = P.seed | 0;

// deterministic uniform hash (no p5 random); Math.imul keeps the 32-bit mix exact
const gh = (i, s) => { let h = (i * 374761393 + s * 668265263 + seedI * 2654435761) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); h ^= h >>> 16; return (h >>> 0) / 4294967296; };

// ---- (re)build grid on size / seed / states change ----
const buildSig = CW + 'x' + CH + '_' + seedI + '_' + N;
const NC = CW * CH;

// ---- clock -> generations/sec (continuous K.t drives evolution; never re-phases) ----
const gps = 1.5 + P.speed * 4 + K.intensity * 2;
const target = Math.floor(K.t * gps);

if (S.buildSig !== buildSig || !S.state) {
  S.buildSig = buildSig;
  S.state = new Uint8Array(NC);
  S.state2 = new Uint8Array(NC);
  S.age = new Uint8Array(NC);
  for (let k = 0; k < NC; k++) S.state[k] = (gh(k, 4242) * N) | 0;
  S.step = target;
}

// ---- Greenberg-Hastings / cyclic CA step: cell -> (s+1)%N if any Moore(r1) neighbor holds (s+1)%N ----
function evolve() {
  const st = S.state, ag = S.age, nx = S.state2;
  for (let j = 0; j < CH; j++) {
    const jm = (j - 1 + CH) % CH, jp = (j + 1) % CH, rj = j * CW, rjm = jm * CW, rjp = jp * CW;
    for (let i = 0; i < CW; i++) {
      const im = (i - 1 + CW) % CW, ip = (i + 1) % CW;
      const idx = rj + i;
      const s = st[idx];
      const nv = s + 1 === N ? 0 : s + 1;
      let c = 0;
      if (st[rjm + im] === nv) c++;
      if (st[rjm + i] === nv) c++;
      if (st[rjm + ip] === nv) c++;
      if (st[rj + im] === nv) c++;
      if (st[rj + ip] === nv) c++;
      if (st[rjp + im] === nv) c++;
      if (st[rjp + i] === nv) c++;
      if (st[rjp + ip] === nv) c++;
      if (c >= 1) { nx[idx] = nv; ag[idx] = 0; }
      else { nx[idx] = s; const a = ag[idx]; if (a < 250) ag[idx] = a + 1; }
    }
  }
  const tmp = S.state; S.state = S.state2; S.state2 = tmp;
}

// ---- reseed a wandering disc so fresh spirals keep nucleating ----
function reseedPatch(cx, cy, rad, gen) {
  const st = S.state, ag = S.age, r2 = rad * rad;
  for (let dj = -rad; dj <= rad; dj++) {
    for (let di = -rad; di <= rad; di++) {
      if (di * di + dj * dj > r2) continue;
      const i = ((cx + di) % CW + CW) % CW, j = ((cy + dj) % CH + CH) % CH;
      const idx = j * CW + i;
      st[idx] = (gh(i * 7 + 3, j * 13 + gen) * N) | 0;
      ag[idx] = 0;
    }
  }
}

// ---- section-driven dramaturgy: palette drift, reseed cadence, wandering nucleus ----
const secN = Math.floor(K.section) % 8;
const hueOff = P.hue + secN * 15 + K.t * 1.8;
const RP = Math.max(6, Math.round(38 - P.density * 28 - secN * 1.2));
const rad = Math.max(3, Math.round((0.10 + P.density * 0.11) * Math.min(CW, CH)));
const cx = Math.floor(P.x * CW + Math.sin(K.t * 0.13) * CW * 0.22);
const cy = Math.floor(P.y * CH + Math.cos(K.t * 0.11) * CH * 0.22);

// ---- advance generations (guard t0 resets, cap catch-up) ----
if (S.step == null || target < S.step) S.step = target;
if (target - S.step > CH * 2) {
  S.step = target;
} else {
  let guard = 0;
  while (S.step < target && guard < 6) {
    evolve();
    S.step++; guard++;
    if (S.step % RP === 0) reseedPatch(cx, cy, rad, S.step);
    if (S.step % 53 === 0) { const si = (gh(9, S.step) * CW) | 0, sj = (gh(11, S.step) * CH) | 0; S.state[sj * CW + si] = (gh(13, S.step) * N) | 0; }
  }
}

// ---- coarse buffer ----
if (!S.g || S.gw !== CW || S.gh !== CH) { S.g = createGraphics(CW, CH); S.g.pixelDensity(1); S.gw = CW; S.gh = CH; }

// ---- HSV -> rgb 0..255 into shared triple (no per-pixel alloc) ----
const OUT = [0, 0, 0];
function setHSV(o, h, s, v) {
  h = ((h % 360) + 360) % 360; const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r = c; g = x; b = 0; } else if (h < 120) { r = x; g = c; b = 0; } else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; } else if (h < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  o[0] = (r + m) * 255; o[1] = (g + m) * 255; o[2] = (b + m) * 255;
}
const eexp = Math.min(1.35, 0.5 + P.energy * 0.85 + K.intensity * 0.25 + A.rms * 0.5);
const freshOf = a => a === 0 ? 1 : (a === 1 ? 0.55 : (a === 2 ? 0.28 : (a === 3 ? 0.14 : 0.05)));
const style = P.style;

let col;
if (style === 'ember') {
  col = (s, a) => { const sn = s / N, f = freshOf(a), heat = sn * 0.7 + f * 0.4; const v = Math.min(1, (0.14 + heat * 0.9) * eexp); setHSV(OUT, 6 + sn * 46 + f * 10 + hueOff * 0.05, Math.max(0.5, 1 - heat * 0.35), Math.max(0.07, v)); };
} else if (style === 'ocean') {
  col = (s, a) => { const sn = s / N, f = freshOf(a); const v = Math.min(1, (0.28 + sn * 0.32 + f * 0.5) * eexp); setHSV(OUT, 150 + sn * 110 + f * 22 + hueOff * 0.06, 0.78, Math.max(0.13, v)); };
} else if (style === 'phosphor') {
  col = (s, a) => { const sn = s / N, f = freshOf(a); const v = Math.min(1, (0.1 + sn * 0.42 + f * 0.55) * eexp); setHSV(OUT, 118 + (sn - 0.5) * 26, 0.85, Math.max(0.04, v)); };
} else if (style === 'duotone') {
  col = (s, a) => { const sn = s / N, f = freshOf(a), band = sn < 0.5 ? 0 : 1; const v = Math.min(1, (band ? 0.58 : 0.34) * (0.7 + 0.5 * f) * eexp); setHSV(OUT, band ? hueOff : hueOff + 165, band ? 0.72 : 0.88, Math.max(0.09, v)); };
} else { // pinwheel (default) — full rainbow hue wheel, glowing wavefronts
  col = (s, a) => { const sn = s / N, f = freshOf(a); const v = Math.min(1, (0.4 + 0.5 * f) * eexp); setHSV(OUT, sn * 360 + hueOff, 0.82, Math.max(0.22, v)); };
}

// ---- render buffer (rebuild on generation / live-poke change) ----
const rsig = S.step + '|' + style + '|' + Math.round(hueOff) + '|' + Math.round(eexp * 20) + '|' + N + '|' + CW + 'x' + CH;
if (S.rsig !== rsig) {
  S.rsig = rsig;
  const g = S.g; g.loadPixels(); const px = g.pixels, st = S.state, ag = S.age;
  if (style === 'contour') {
    for (let j = 0; j < CH; j++) {
      const jp = (j + 1) % CH, rj = j * CW, rjp = jp * CW;
      for (let i = 0; i < CW; i++) {
        const ip = (i + 1) % CW, idx = rj + i, s = st[idx];
        const edge = (st[rj + ip] !== s) || (st[rjp + i] !== s);
        if (edge) { const sn = s / N, f = freshOf(ag[idx]); setHSV(OUT, sn * 320 + hueOff, 0.55, Math.min(1, (0.68 + 0.4 * f) * eexp)); }
        else setHSV(OUT, hueOff, 0.4, 0.05);
        const o = 4 * idx; px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
      }
    }
  } else {
    for (let k = 0; k < NC; k++) {
      col(st[k], ag[k]);
      const o = 4 * k; px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
    }
  }
  g.updatePixels();
}

// ---- draw: upscale with slow continuous rotation + zoom breath (motion floor, overscanned so no black edges) ----
const ang = K.t * 0.02;
const zoom = 1.52 + Math.sin(K.t * 0.11) * 0.05 + A.rms * 0.14;
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
translate(width / 2, height / 2);
rotate(ang);
scale(zoom);
imageMode(CENTER);
image(S.g, 0, 0, width, height);
pop();
imageMode(CORNER);

// ---- CRT scanlines for phosphor (screen-space, cached) ----
if (style === 'phosphor') {
  if (!S.scan || S.scanH !== (height | 0)) {
    S.scan = createGraphics(4, Math.max(2, height | 0)); S.scan.pixelDensity(1);
    const sc = S.scan; sc.loadPixels(); const pp = sc.pixels;
    for (let y = 0; y < sc.height; y++) { const av = (y % 3 === 0) ? 64 : 0; for (let xx = 0; xx < 4; xx++) { const o = 4 * (y * 4 + xx); pp[o] = 0; pp[o + 1] = 0; pp[o + 2] = 0; pp[o + 3] = av; } }
    sc.updatePixels(); S.scanH = (height | 0);
  }
  image(S.scan, 0, 0, width, height);
}

// ---- audio glow ON TOP of clk baseline (all-zero during validation; partial alpha, never strobes) ----
if (A.bass > 0.01 || A.treble > 0.01 || A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  fill((hueOff + 20) % 360, 40, 100, (A.bass * 0.6 + A.rms * 0.4) * P.energy * 16);
  rect(0, 0, width, height);
  fill((hueOff + 60) % 360, 55, 100, A.treble * P.energy * 12);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
